pub struct Disclosure { expanded: bool }              // behaviour: owns the state
impl Disclosure {
    pub fn new() -> Self { Self { expanded: false } }
    pub fn toggle(&mut self) { self.expanded = !self.expanded; }
    pub fn view<R>(&self, markup: impl FnOnce(&Self) -> R) -> R { markup(self) }
}
